(function(root){
'use strict';
const candidates=typeof module==='object'&&module.exports?require('./library.js').cases:root.NavigatorLibrary.getCases();
const checked=c=>c.verificationLevel==='primary-verified'&&c.verifiedAt&&/^[a-f0-9]{64}$/.test(c.sourceSha256||'')&&['identity','primaryText','proposition','pinpoint','disposition'].every(k=>c.verification?.[k]===true);
const data=candidates.filter(checked);
const kind=c=>c.decisionType||(/Commission/i.test(c.forum)?'Information Commission order':/Tribunal/i.test(c.forum)?'Tribunal order':/Supreme/i.test(c.forum)?'Supreme Court judgment / order':'High Court judgment / order');
const normal=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const topics=[...new Set(data.flatMap(c=>(c.topics?.length?c.topics:['Other POSH authorities'])))].sort();
function filter(q='',topic='All topics',type='All forums',status='all'){const words=normal(q).split(' ').filter(Boolean);return data.filter(c=>(topic==='All topics'||((c.topics?.length?c.topics:['Other POSH authorities'])).includes(topic))&&(type==='All forums'||kind(c).startsWith(type))&&(status==='all'||(status==='checked'?checked(c):!checked(c)))&&words.every(w=>normal([c.id,c.masterId,c.title,c.caseNumber,c.citation,c.date,c.basis,c.note,c.caution,c.pinpoint,...(c.topics||[])].join(' ')).includes(w))).sort((a,b)=>Number(checked(b))-Number(checked(a))||a.id.localeCompare(b.id));}
if(typeof module==='object'&&module.exports){module.exports={data,checked,kind,filter,topics};return;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(app,path){let page=0;const params=new URLSearchParams(location.hash.split('?')[1]||''),selected=path.startsWith('faq/case-')?data.find(c=>c.id===path.split('case-')[1].toUpperCase()):null;app.innerHTML=`<section class="app-heading"><div class="wrap"><div><a class="app-back" href="#faq">← FAQs</a><small>THE COSMIC ENERGIZERS · CASE LAW</small><h1>Verified judgments, by issue.</h1><p>${data.length} judgments checked against original court text. Find the legal point, exact decision, pinpoint and limits.</p><nav class="knowledge-tabs" aria-label="Knowledge library"><a href="#faq">All FAQs <strong>${root.NavigatorFinder.count}</strong></a><a href="#faq/cases" aria-current="page">Judgments &amp; orders <strong>${data.length}</strong></a></nav></div></div></section><div class="app-bg"><div class="wrap workspace finder-shell"><section class="finder-controls"><label for="case-search">Search case name, citation, section or issue</label><input id="case-search" type="search" maxlength="160" autocomplete="off" placeholder="Try: Vishaka, fair hearing, Section 18 or POSH-0004"><div class="case-filters"><label>Issue<select id="case-topic"><option>All topics</option>${topics.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>Forum<select id="case-forum"><option>All forums</option><option>Supreme Court</option><option>High Court</option><option>Tribunal</option><option>Information Commission</option></select></label><label>Source check<select id="case-status"><option value="all">Verified judgments only</option></select></label></div><button id="case-reset" class="btn btn-light" type="button">Show all authorities</button></section><p class="faq-general-note">Verified on 1 November 2026 for the decision and proposition stated. Open each source note for case-specific later-proceeding limits.</p><p id="case-count" role="status" aria-live="polite"></p><div id="case-results"></div><p id="case-empty" hidden>No matching verified judgment. This reference may be outside the verified public collection. Choose “Show all authorities” to browse available judgments.</p><nav class="library-pagination" aria-label="Case pages"><button id="case-prev" type="button" class="btn btn-light">Previous</button><span id="case-page"></span><button id="case-next" type="button" class="btn btn-light">Next</button></nav></div></div>`;
const input=app.querySelector('#case-search'),topic=app.querySelector('#case-topic'),forum=app.querySelector('#case-forum'),status=app.querySelector('#case-status');input.value=selected?selected.id:path.startsWith('faq/case-')?'unavailable-reference':(params.get('q')||'').slice(0,160);if(topics.includes(params.get('topic')))topic.value=params.get('topic');if(['checked','research'].includes(params.get('status')))status.value=params.get('status');if(['Supreme Court','High Court','Tribunal','Information Commission'].includes(params.get('forum')))forum.value=params.get('forum');page=Math.max(0,Number(params.get('page')||1)-1);
function apply(persist=true){const list=filter(input.value,topic.value,forum.value,status.value);page=Math.min(page,Math.max(0,Math.ceil(list.length/12)-1));const visible=list.slice(page*12,page*12+12);app.querySelector('#case-count').textContent=`${list.length} of ${data.length} authorities · ${data.filter(checked).length} verified against original judgment text`;app.querySelector('#case-results').innerHTML=visible.map(c=>{const related=[...new Map([...(c.relatedFAQs||[]).map(id=>root.NavigatorFinder.recordFor(id)),...root.NavigatorFinder.getIndex().filter(x=>(x.cases||[]).includes(c.id)||x.members.some(m=>(m.cases||[]).includes(c.id)))].filter(Boolean).map(x=>[x.id,x])).values()].slice(0,5);return `<article class="case-record" id="case-${c.id.toLowerCase()}" data-case-id="${c.id}"><div class="case-record-meta"><span>${esc(c.id)}${c.masterId?' · '+esc(c.masterId):''}</span><span>${esc(kind(c))}</span><span>Verified judgment text</span></div><h2>${esc(c.title)}</h2><p class="case-citation">${esc(c.caseNumber||c.citation||'Citation identity requires verification')} · ${esc(c.date||'Decision date requires verification')}</p><p><strong>Forum:</strong> ${esc(c.forum||'Forum requires verification')}</p>${c.note?`<p><strong>Legal point:</strong> ${esc(c.note)}</p>`:'<p>The precise proposition remains a research task. Read the source and verification status before citing this record.</p>'}${c.basis?`<p><strong>Provisions / framework:</strong> ${esc(c.basis)}</p>`:''}${c.pinpoint?`<p><strong>Pinpoint:</strong> ${esc(c.pinpoint)}</p>`:''}${c.caution?`<p><strong>Limits:</strong> ${esc(c.caution)}</p>`:''}<details class="case-source-status"><summary>Verification and subsequent-proceeding details</summary><p>${esc(c.status)}</p>${c.checkedAt?`<p>Verified: ${esc(c.verifiedAt)}</p>`:''}${c.laterSource?`<p><a href="${esc(c.laterSource)}" target="_blank" rel="noopener noreferrer">Read the inspected later order ↗</a></p>`:''}${c.serviceRules?`<p>Service rules: ${esc(c.serviceRules)}</p>`:''}</details><nav class="case-source-links">${c.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Read judgment / order text ↗</a>`:'<span>Original source link not yet established.</span>'}<a href="#faq/case-${c.id.toLowerCase()}">Link to this authority</a></nav>${related.length?`<nav class="faq-related" aria-label="Related FAQs"><strong>Related FAQs</strong>${related.map(x=>`<a href="#faq/${esc(x.id)}">FAQ ${x.number} · ${esc(x.question)}</a>`).join('')}</nav>`:''}</article>`}).join('');app.querySelector('#case-empty').hidden=!!list.length;app.querySelector('#case-prev').disabled=page===0;app.querySelector('#case-next').disabled=(page+1)*12>=list.length;app.querySelector('#case-page').textContent=`Page ${page+1} of ${Math.max(1,Math.ceil(list.length/12))}`;if(persist){const p=new URLSearchParams();if(input.value)p.set('q',input.value);if(topic.value!=='All topics')p.set('topic',topic.value);if(status.value!=='all')p.set('status',status.value);if(forum.value!=='All forums')p.set('forum',forum.value);if(page)p.set('page',String(page+1));history.replaceState(null,'','#faq/cases'+(p.size?'?'+p.toString():''));}}
for(const el of [input,topic,forum,status])el.addEventListener(el===input?'input':'change',()=>{page=0;apply()});app.querySelector('#case-reset').onclick=()=>{input.value='';topic.value='All topics';forum.value='All forums';status.value='all';page=0;apply();};const focus=()=>{app.querySelector('#case-count').scrollIntoView({block:'start'});};app.querySelector('#case-prev').onclick=()=>{page--;apply();focus()};app.querySelector('#case-next').onclick=()=>{page++;apply();focus()};apply(false);document.title=`${data.length} POSH judgments and orders | The Cosmic Energizers`;
}
root.NavigatorCases={render,count:data.length};
})(typeof window==='undefined'?globalThis:window);
